{
  "findings": [
    {
      "check_id": "CKV_AWS_16",
      "title": "Ensure all data stored in the RDS is securely encrypted at rest",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "HIGH",
      "explanation": "The `storage_encrypted` attribute is not set, defaulting to false. This means database storage and snapshots are not encrypted at rest, violating security best practices for data protection."
    },
    {
      "check_id": "CKV_AWS_293",
      "title": "Ensure that AWS database instances have deletion protection enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `deletion_protection` attribute is not set, defaulting to false. This allows accidental or malicious deletion of the database instance without safeguards."
    },
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `multi_az` attribute is explicitly set to \"false\". For production workloads, Multi-AZ deployment is recommended to provide high availability and automatic failover."
    },
    {
      "check_id": "CKV_AWS_129",
      "title": "Ensure that respective logs of Amazon Relational Database Service (Amazon RDS) are enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `enable_log_exports_to_cloudwatch_logs` attribute is missing. Enabling log exports is critical for auditing, troubleshooting, and security monitoring of database activities."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n  storage_encrypted = true\n  deletion_protection = true\n  enable_log_exports_to_cloudwatch_logs = true\n}",
  "fix_summary": "Enabled storage encryption (`storage_encrypted = true`) to protect data at rest. Enabled deletion protection (`deletion_protection = true`) to prevent accidental removal. Changed `multi_az` from false to true for high availability. Added `enable_log_exports_to_cloudwatch_logs = true` to ensure audit logs are exported for security monitoring."
}
